const fastify = require('fastify')({ logger: false });

fastify.get('/', async (request, reply) => {
  return 'Hallo, Welt!';
});

fastify.listen({ port: 3000 }, (err, address) => {
  if (err) {
    console.error(err);
    process.exit(1);
  }
  console.log(`Fastify läuft auf ${address}`);
});
